/**
 * exportImage — the exact, byte-stable export path.
 * Uses ImagePipeline.renderExport; the preview code never touches this.
 */

import { createHash } from "node:crypto";
import { ImagePipeline } from "./pipeline.ts";

export interface ExportResult {
  bytes: Uint8Array;
  sha256: string;
}

export function exportImage(pipeline: ImagePipeline, intensity: number): ExportResult {
  const bytes = pipeline.renderExport(intensity);
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  return { bytes, sha256 };
}

/**
 * ImagePipeline — the public API an Intent Lock would pin.
 * renderPreview: fast approximate path used during drag.
 * renderExport: the exact path; its output must stay byte-identical.
 */

export interface PreviewFrame {
  width: number;
  height: number;
  pixels: Uint8Array;
}

export interface SourceImage {
  width: number;
  height: number;
  pixels: Uint8Array;
}

export class ImagePipeline {
  private source: SourceImage;

  constructor(source: SourceImage) {
    this.source = source;
  }

  /** Approximate, downscaled render for interactive preview. */
  renderPreview(intensity: number, maxDim = 512): PreviewFrame {
    const scale = Math.min(1, maxDim / Math.max(this.source.width, this.source.height));
    const width = Math.max(1, Math.round(this.source.width * scale));
    const height = Math.max(1, Math.round(this.source.height * scale));
    const down = downscale(this.source, width, height);
    return { width, height, pixels: applyIntensity(down, intensity) };
  }

  /** Exact full-resolution render used by export. Byte-stable output. */
  renderExport(intensity: number): Uint8Array {
    return applyIntensity(this.source.pixels, intensity);
  }

  describe(): string {
    return `ImagePipeline(${this.source.width}x${this.source.height})`;
  }
}

export function applyIntensity(pixels: Uint8Array, intensity: number): Uint8Array {
  const out = new Uint8Array(pixels.length);
  const k = intensity;
  for (let i = 0; i < pixels.length; i++) {
    out[i] = Math.round(pixels[i] * k);
  }
  return out;
}

export function downscale(img: SourceImage, width: number, height: number): Uint8Array {
  const out = new Uint8Array(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const sx = Math.floor((x / width) * img.width);
      const sy = Math.floor((y / height) * img.height);
      out[y * width + x] = img.pixels[sy * img.width + sx];
    }
  }
  return out;
}

function clamp01(x: number): number {
  return Math.min(1, Math.max(0, x));
}

import assert from "node:assert";
import test from "node:test";
import { ImagePipeline, type SourceImage } from "../src/pipeline.ts";
import { exportImage } from "../src/export.ts";

function fixture(): SourceImage {
  return { width: 4, height: 4, pixels: new Uint8Array(16).map((_, i) => i * 16) };
}

test("renderExport is byte-identical for identical input", () => {
  const a = exportImage(new ImagePipeline(fixture()), 0.5);
  const b = exportImage(new ImagePipeline(fixture()), 0.5);
  assert.deepStrictEqual([...a.bytes], [...b.bytes]);
  assert.strictEqual(a.sha256, b.sha256);
});

test("renderPreview downscales to maxDim", () => {
  const pipe = new ImagePipeline({ width: 2048, height: 1024, pixels: new Uint8Array(2048 * 1024) });
  const frame = pipe.renderPreview(1, 512);
  assert.strictEqual(frame.width, 512);
  assert.strictEqual(frame.height, 256);
});

test("slider emits after debounce and on drag end", async () => {
  const { SliderBinding } = await import("../src/slider.ts");
  const s = new SliderBinding(10);
  let emissions = 0;
  s.onChange(() => emissions++);
  s.beginDrag();
  s.setValue(0.8);
  s.endDrag();
  assert.ok(emissions >= 1, "expected at least one emission on drag end");
});

/**
 * SliderBinding — debounced intensity slider for the preview.
 * Emits the current intensity while dragging, coalescing rapid movements
 * so the pipeline does not re-render on every tiny movement.
 */

export interface SliderState {
  /** 0..1 */
  value: number;
  dragging: boolean;
}

export type SliderListener = (state: SliderState) => void;

export class SliderBinding {
  private state: SliderState = { value: 0.5, dragging: false };
  private listeners: SliderListener[] = [];
  private pending: ReturnType<typeof setTimeout> | null = null;
  private debounceMs: number;

  constructor(debounceMs = 40) {
    this.debounceMs = debounceMs;
  }

  onChange(listener: SliderListener): void {
    this.listeners.push(listener);
  }

  beginDrag(): void {
    this.state = { ...this.state, dragging: true };
  }

  setValue(value: number): void {
    this.state = { value: clamp01(value), dragging: this.state.dragging };
    this.scheduleEmit();
  }

  endDrag(): void {
    this.state = { ...this.state, dragging: false };
    this.flush();
  }

  current(): SliderState {
    return this.state;
  }

  private scheduleEmit(): void {
    if (this.pending) clearTimeout(this.pending);
    this.pending = setTimeout(() => this.flush(), this.debounceMs);
  }

  private flush(): void {
    if (this.pending) {
      clearTimeout(this.pending);
      this.pending = null;
    }
    for (const listener of this.listeners) listener(this.state);
  }
}

export function clamp01(x: number): number {
  return Math.min(1, Math.max(0, x));
}

